 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Separator rows/columns are the regularly repeated lines that differ
    # from the tile background over most of their length.
    rows = [r for r in range(h) if sum(v != background for v in grid[r]) > w / 2]
    cols = [c for c in range(w) if sum(grid[r][c] != background for r in range(h)) > h / 2]

    if len(rows) < 2 or len(cols) < 2:
        return [[background]]

    return [
        [
            (grid[rows[i]][cols[j]]
             if grid[rows[i]][cols[j]] == grid[rows[i]][cols[j + 1]]
             == grid[rows[i + 1]][cols[j]] == grid[rows[i + 1]][cols[j + 1]]
             else background)
            for j in range(len(cols) - 1)
        ]
        for i in range(len(rows) - 1)
    ]


if __name__ == '__main__':
